config.script:
// Which record a Liberty1 click is for (#1545). The portal posts {Prospect__c}
// or {Submission__c}, whichever it has. A Prospect__c that is a Salesforce id is
// queried directly. Otherwise a Submission__c that is one queries the
// submission itself, with its Lead and, through Prospect__r, every field of the
// prospect it points at, so pick_record can send from the prospect when there
// is one and from the submission when there is not (Brian, 2026-09-29). A
// Submission__c posted beside a usable Prospect__c is ignored: nothing ties that
// submission to this prospect.
//
// An id is interpolated into SOQL, so anything that is not exactly 15 or 18
// letters and digits is refused here and never reaches a query. valid false
// sends the run to the 400 response, with the reason named.
const SF_ID = /^[A-Za-z0-9]{15}(?:[A-Za-z0-9]{3})?$/;

// Brian's PROSPECT_FIELDS, then the two fields the offer check reads.
const FIELDS = [
  "Id", "SubaccountName__c", "SubaccountUUID__c", "First_Name__c", "Last_Name__c", "Email__c",
  "Phone__c", "Street__c", "AptSuite__c", "City__c", "State__c", "Zip__c", "BirthDate__c",
  "SocialSecurityNumber__c", "LoanPurpose__c", "LoanAmount__c", "RentOrOwn__c",
  "ApproximateCreditRating__c", "EmploymentStatus__c", "IncomePmtFrequency__c",
  "AnnualIncomeBeforeTaxes__c", "EducationLevel__c", "FCRAConsentFlag__c", "TCPAConsentFlag__c",
  "User_IP__c", "ExternalRoutingCode__c", "ExternalExchangeStatus__c",
];

// Brian's SUBMISSION_FIELDS (the applicant lives in the *_SO__c fields, the
// phone on the Lead), then the submission's two offer fields.
const SUBMISSION_FIELDS = [
  "Id", "Prospect__c", "Lead__c", "Source__c", "FundedDemandSubAccountName__c", "SubaccountUUID__c",
  "Prospect_Subaccount_UUID__c", "FirstNameSO__c", "LastNameSO__c", "Email_SO__c", "Home_Phone__c",
  "StreetSO__c", "Apt_Suite_SO__c", "City_SO__c", "State_SO__c", "Zip_Code_SO__c",
  "Date_of_Birth_SO__c", "Social_Security_Number_SO__c", "Loan_Purpose_SO__c", "Loan_Amount_SO__c",
  "Rent_or_Own_SO__c", "Approximate_Credit_Rating_SO__c", "Employment_Status_SO__c",
  "Income_Pmt_Frequency_SO__c", "Annual_Income_Before_Taxes_SO__c", "Education_Level_SO__c",
  "ConsentFCRA__c", "Consent__c", "User_IP__c",
  "Lead__r.FirstName", "Lead__r.LastName", "Lead__r.Email", "Lead__r.Phone", "Lead__r.MobilePhone",
  "External_Routing_Code__c", "External_Exchange_Status__c",
];

const body = payload !== null && typeof payload === "object" && !Array.isArray(payload) ? payload : {};

const present = (v) => v !== undefined && v !== null && !(typeof v === "string" && v.trim() === "");
const asId = (v) => (typeof v === "string" && SF_ID.test(v.trim()) ? v.trim() : null);

const prospectId = asId(body.Prospect__c);
const submissionId = asId(body.Submission__c);

if (prospectId) {
  return {
    valid: true,
    reason: null,
    source: "prospect",
    prospect_id: prospectId,
    submission_id: null,
    soql: `SELECT ${FIELDS.join(", ")} FROM Prospect__c WHERE Id = '${prospectId}'`,
  };
}

if (submissionId) {
  const selected = [...SUBMISSION_FIELDS, ...FIELDS.map((f) => `Prospect__r.${f}`)];
  return {
    valid: true,
    reason: null,
    source: "submission",
    prospect_id: null,
    submission_id: submissionId,
    soql: `SELECT ${selected.join(", ")} FROM Submission__c WHERE Id = '${submissionId}'`,
  };
}

return {
  valid: false,
  reason: present(body.Prospect__c) || present(body.Submission__c) ? "invalid_id" : "no_id",
  source: null,
  prospect_id: null,
  submission_id: null,
  soql: null,
};

// Which record a Liberty1 click sends, and whether it may be sent (#1547). Reads
// the one row query_record returned for resolve_input's query.
//
// A Prospect__c click, or a Submission__c whose Prospect__r came back, is judged
// on the PROSPECT: open only with Liberty1's routing code 4 and status Bid, which
// the Engine Bidding offer writes, and completed when that offer is already
// Completed. Anything else was never offered Liberty1.
//
// A Submission with NO Prospect is TRUSTED (Dan, 2026-09-29): nothing writes a
// Liberty1 offer onto a Submission before the click, so there is no mark to
// check, and it is sent from the submission itself with Brian's mapping below.
// A submission already Completed is never sent: for Liberty1 (code 4) it is
// answered already sent, and for any other buyer it is refused as no Liberty1
// offer (Dan, 2026-09-29), as a prospect sold elsewhere is, so one person is not
// sold twice. The claim in click_send keys it on the submission id, so a repeat
// click is never sent twice.
//
// A Submission that names a Prospect the query could not return is not found
// as a prospect, never sent from the submission instead.
const OFFER_CODE = "4";

// Map a Submission onto the Prospect field names so buildPayload() handles both
// (Brian's submissionAsProspect, verbatim).
function submissionAsProspect(s) {
  const lead = s.Lead__r || {};
  return {
    Id: s.Id,
    SubaccountName__c: s.FundedDemandSubAccountName__c ?? s.Source__c,
    SubaccountUUID__c: s.SubaccountUUID__c ?? s.Prospect_Subaccount_UUID__c,
    First_Name__c: s.FirstNameSO__c ?? lead.FirstName,
    Last_Name__c: s.LastNameSO__c ?? lead.LastName,
    Email__c: s.Email_SO__c ?? lead.Email,
    Phone__c: lead.MobilePhone ?? lead.Phone ?? s.Home_Phone__c,
    Street__c: s.StreetSO__c,
    AptSuite__c: s.Apt_Suite_SO__c,
    City__c: s.City_SO__c,
    State__c: s.State_SO__c,
    Zip__c: s.Zip_Code_SO__c,
    BirthDate__c: s.Date_of_Birth_SO__c,
    SocialSecurityNumber__c: s.Social_Security_Number_SO__c,
    LoanPurpose__c: s.Loan_Purpose_SO__c,
    LoanAmount__c: s.Loan_Amount_SO__c,
    RentOrOwn__c: s.Rent_or_Own_SO__c,
    ApproximateCreditRating__c: s.Approximate_Credit_Rating_SO__c,
    EmploymentStatus__c: s.Employment_Status_SO__c,
    IncomePmtFrequency__c: s.Income_Pmt_Frequency_SO__c,
    AnnualIncomeBeforeTaxes__c: s.Annual_Income_Before_Taxes_SO__c,
    EducationLevel__c: s.Education_Level_SO__c,
    FCRAConsentFlag__c: s.ConsentFCRA__c,
    TCPAConsentFlag__c: s.Consent__c,
    User_IP__c: s.User_IP__c,
  };
}

const isOffer = (code) => code !== null && code !== undefined && String(code) === OFFER_CODE;
const prospectVerdict = (p) => {
  if (!isOffer(p.ExternalRoutingCode__c)) return "no_offer";
  if (p.ExternalExchangeStatus__c === "Completed") return "completed";
  if (p.ExternalExchangeStatus__c === "Bid") return "open";
  return "no_offer";
};
const idOf = (v) => (typeof v === "string" && v.trim() !== "" ? v : null);

const source = steps.resolve_input?.output?.source;
if (source !== "prospect" && source !== "submission") {
  throw new Error(`pick_record: resolve_input named no source (${JSON.stringify(source ?? null)}), so the row cannot be read as either object`);
}

const row = steps.query_record?.output?.body?.records?.[0] ?? null;
const notFound = (what) => ({
  verdict: "not_found",
  not_found_outcome: what,
  offer: null,
  record: null,
  prospect_id: null,
  submission_id: null,
  lead_id: null,
  sale_key: null,
});

if (!row || !idOf(row.Id)) return notFound(source === "prospect" ? "prospect_not_found" : "submission_not_found");

if (source === "prospect") {
  return {
    verdict: prospectVerdict(row),
    not_found_outcome: null,
    offer: "on_record",
    record: row,
    prospect_id: row.Id,
    submission_id: null,
    lead_id: null,
    sale_key: row.Id,
  };
}

const leadId = idOf(row.Lead__c);

if (idOf(row.Prospect__c)) {
  const prospect = row.Prospect__r;
  if (!prospect || !idOf(prospect.Id)) return notFound("prospect_not_found");
  return {
    verdict: prospectVerdict(prospect),
    not_found_outcome: null,
    offer: "on_record",
    record: prospect,
    prospect_id: prospect.Id,
    submission_id: row.Id,
    lead_id: leadId,
    sale_key: prospect.Id,
  };
}

const sold = row.External_Exchange_Status__c === "Completed";
const soldToLiberty1 = sold && isOffer(row.External_Routing_Code__c);
return {
  verdict: soldToLiberty1 ? "completed" : sold ? "no_offer" : "open",
  not_found_outcome: null,
  offer: "trusted",
  record: submissionAsProspect(row),
  prospect_id: null,
  submission_id: row.Id,
  lead_id: leadId,
  sale_key: row.Id,
};

// The Liberty1 request for one click (#1545): Brian's buildPayload and his DV1
// or DI4 route, unchanged, over the record pick_record chose (a prospect, or a
// submission mapped onto prospect field names). Pure: buyer_click_send posts
// it, this only builds it.
//
// Back on the Liberty1 Salesforce site on 2026-09-29, where Brian's flow posts
// "until later in the week"; the LeadConnector routes it used from 2026-09-25
// return when Liberty1 moves again.
const LIBERTY1_BASE =
  "https://liberty1financial.my.salesforce-sites.com/L1F/services/apexrest/inbound/webhooks";

const DV1_STATES = new Set(["DE", "HI", "IA", "MN", "OR", "RI", "VT", "WA", "WI", "WY"]);

const ROUTES = {
  DV1: `${LIBERTY1_BASE}/DV1`,
  DI4: `${LIBERTY1_BASE}/DI4`, // all other states
};

const clean = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s === "" ? null : s;
};
const digits = (v) => { const s = clean(v); return s === null ? null : s.replace(/\D/g, ""); };
const phone10 = (v) => { const d = digits(v); if (d === null) return null; return d.length === 11 && d.startsWith("1") ? d.slice(1) : d; };
const zip5 = (v) => { const d = digits(v); return d === null ? null : d.slice(0, 5); };
const titleCase = (v) => { const s = clean(v); return s === null ? null : s.toLowerCase().replace(/(^|[\s\-'])([a-z])/g, (_, sep, c) => sep + c.toUpperCase()); };
const upper = (v) => { const s = clean(v); return s === null ? null : s.toUpperCase(); };
const lower = (v) => { const s = clean(v); return s === null ? null : s.toLowerCase(); };
// Picklist value -> API enum: "Poor (<600)" -> "poor", "Own with Mortgage" -> "own_with_mortgage"
const toEnum = (v) => { const s = clean(v); if (s === null) return null; return s.replace(/\s*\(.*?\)\s*/g, " ").trim().toLowerCase().replace(/\s+/g, "_"); };
const num = (v) => { if (v === null || v === undefined || v === "") return null; const n = Number(v); return Number.isFinite(n) ? n : null; };
const address1 = (street, apt) => {
  const s = clean(street); const a = clean(apt);
  if (s === null) return a; if (a === null) return s;
  return /^(apt|unit|ste|suite|#)/i.test(a) ? `${s} ${a}` : `${s} Apt ${a}`;
};

function buildPayload(p) {
  return {
    leadId1: p.Id,
    leadId2: clean(p.SubaccountName__c),
    leadId3: clean(p.SubaccountUUID__c),
    firstName: clean(p.First_Name__c),
    lastName: clean(p.Last_Name__c),
    email: lower(p.Email__c),
    primaryPhone: phone10(p.Phone__c),
    address1: address1(p.Street__c, p.AptSuite__c),
    city: titleCase(p.City__c),
    state: upper(p.State__c),
    zipcode: zip5(p.Zip__c),
    dateOfBirth: clean(p.BirthDate__c),
    ssn: digits(p.SocialSecurityNumber__c),
    purpose: toEnum(p.LoanPurpose__c),
    loanAmount: num(p.LoanAmount__c),
    propertyStatus: toEnum(p.RentOrOwn__c),
    providedCreditRating: toEnum(p.ApproximateCreditRating__c),
    employmentStatus: toEnum(p.EmploymentStatus__c),
    employmentPayFrequency: toEnum(p.IncomePmtFrequency__c),
    annualIncome: num(p.AnnualIncomeBeforeTaxes__c),
    educationLevel: toEnum(p.EducationLevel__c),
    consentsToFcra: p.FCRAConsentFlag__c === true,
    consentsToTcpa: p.TCPAConsentFlag__c === true,
    ipAddress: clean(p.User_IP__c),
  };
}

const pickRoute = (state) => (state && DV1_STATES.has(state) ? "DV1" : "DI4");

// The offer check before this node routes only an open click here, so an
// absent record is a wiring fault: refuse by name rather than post a body of nulls.
const record = steps.pick_record?.output?.record;
if (!record || !record.Id) {
  throw new Error("build_liberty1_request: no record picked in steps.pick_record, so nothing to send");
}

const body = buildPayload(record);
const route = pickRoute(body.state);

return {
  url: ROUTES[route],
  body,
  route,
  state: body.state,
};

// What the Liberty1 click writes to Salesforce, from buyer_click_send's route
// (#1545): Brian's three update bodies (Submission, Prospect, Lead), unchanged
// in fields and order.
//
// Completed only on `sent` (Liberty1 confirmed it created the record) and Fail
// only on `refused` (Liberty1 turned it down with its own error). Every other
// route writes NOTHING: `unknown` means nobody knows whether Liberty1 created
// the record, and the rest never sent. write false is what the check_write
// branch reads to skip every update node.
//
// Undefined values are dropped so nothing is blanked. PDFlow_3__c, where his
// flow wrote the Pipedream inspect URL, carries this run's Bidspoke link.
const PARTNER_NAME = "Liberty1";
const ROUTING_CODE = 4; // Number on Prospect, Text on Submission/Lead
const LEAD_SALE_TYPE = "Form";
const LIBERTY1_TCPA = `By clicking "Connect with Liberty1 Financial": I expressly agree to Liberty1 Financial's TCPA consent below, Terms & Conditions, Privacy Policy, and Consent for Electronic Communications.

I expressly provide my consent to receive marketing calls and texts/SMS regarding personal loan and debt consolidation products from Clear Vision Financial LLC, doing business as Liberty1 Financial, at the phone number I provided, including via an automatic telephone dialing system or an artificial, prerecorded, or AI-generated voice, even if my number is on a federal, state, or company Do-Not-Call list. I understand that my consent is not a condition of purchasing any goods or services and that my consent may be revoked at any time, such as by replying "STOP" to opt out of SMS or by telling Liberty1 Financial to stop on any call. I also acknowledge that Liberty1 Financial's Terms & Conditions include a Jury Trial Waiver, Class Action Waiver, and Arbitration Agreement, and, if I am a California resident, that the California Privacy Notice describes my privacy rights. Message and data rates may apply, and message frequency varies.

Text HELP for help or text STOP to cancel.`;

const EXCHANGE_STATUS_BY_ROUTE = { sent: "Completed", refused: "Fail" };

const click = steps.click_send?.output ?? {};
const route = typeof click._route === "string" ? click._route : "not_run";
const exchangeStatus = EXCHANGE_STATUS_BY_ROUTE[route] ?? null;

if (exchangeStatus === null) {
  return {
    write: false,
    exchange_status: null,
    prospect: null,
    submission: null,
    lead: null,
    response: { success: false, outcome: route },
  };
}

const dropUndefined = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));
const partnerLeadId = route === "sent" && click.partner_lead_id ? click.partner_lead_id : undefined;
const now = new Date().toISOString();
const link = execution?.bidspoke_link || undefined;

return {
  write: true,
  exchange_status: exchangeStatus,
  prospect: dropUndefined({
    ExternalExchangeStatus__c: exchangeStatus,
    ExternalPartnerLeadId__c: partnerLeadId,
    ExternalPartnerName__c: PARTNER_NAME,
    ExternalRoutingCode__c: ROUTING_CODE,
    TCPA_Consent__c: LIBERTY1_TCPA,
    ExternalTimestamp__c: now,
    PDFlow_3__c: link,
    LeadSaleType__c: LEAD_SALE_TYPE,
  }),
  submission: dropUndefined({
    External_Exchange_Status__c: exchangeStatus,
    External_Partner_Lead_Id__c: partnerLeadId,
    External_Partner_Name__c: PARTNER_NAME,
    External_Routing_Code__c: String(ROUTING_CODE),
    External_TCPA_Consent__c: LIBERTY1_TCPA,
    External_Timestamp__c: now,
    PDFlow_3__c: link,
    LeadSaleType__c: LEAD_SALE_TYPE,
  }),
  lead: dropUndefined({
    External_Exchange_Status__c: exchangeStatus,
    ExternalPartnerLeadId__c: partnerLeadId,
    ExternalPartnerName__c: PARTNER_NAME,
    External_Routing_Code__c: String(ROUTING_CODE),
    TCPAConsent__c: LIBERTY1_TCPA,
    External_Timestamp__c: now,
    LeadSaleType__c: LEAD_SALE_TYPE,
  }),
  response: { success: route === "sent", outcome: route },
};
